","/**
 * Validated environment access. Nothing else in Taskflow reads `process.env`
 * — call sites import `env` (or `loadEnv()` when they need to validate a
 * different source, as the tests do) so a missing or malformed variable fails
 * once, loudly, instead of surfacing as `undefined` deep in a request.
 */
import { SITE_CONFIG } from "./site";

export type AppEnv = {
  nodeEnv: "development" | "test" | "production";
  databasePath: string;
  appUrl: string;
  digestEnabled: boolean;
};

const NODE_ENVS = ["development", "test", "production"] as const;

type NodeEnvValue = (typeof NODE_ENVS)[number];

function readNodeEnv(raw: string | undefined): NodeEnvValue {
  const value = (raw ?? "development").trim();
  const match = NODE_ENVS.find((candidate) => candidate === value);
  return match ?? "development";
}

/** Accepts `1`/`true`/`yes`/`on` (case-insensitive) as true; anything else false. */
function readBoolean(raw: string | undefined, fallback: boolean): boolean {
  if (raw === undefined || raw.trim() === "") return fallback;
  const value = raw.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(value)) return true;
  if (["0", "false", "no", "off"].includes(value)) return false;
  throw new Error(`Invalid boolean environment value: "${raw}"`);
}

function readUrl(raw: string | undefined, fallback: string): string {
  const value = (raw ?? "").trim() || fallback;
  try {
    // Normalises away a trailing slash so `${appUrl}${path}` never doubles up.
    const parsed = new URL(value);
    return parsed.origin + parsed.pathname.replace(/\/$/, "");
  } catch {
    throw new Error(`Invalid TASKFLOW_APP_URL: "${value}"`);
  }
}

/**
 * Reads and validates the environment. Defaults are chosen so a fresh
 * checkout runs with no `.env` at all — the corpus must build offline.
 */
export function loadEnv(source: NodeJS.ProcessEnv = process.env): AppEnv {
  const nodeEnv = readNodeEnv(source.NODE_ENV);
  const databasePath =
    (source.TASKFLOW_DB_PATH ?? "").trim() ||
    (nodeEnv === "test" ? ":memory:" : "./data/taskflow.db");

  return {
    nodeEnv,
    databasePath,
    appUrl: readUrl(source.TASKFLOW_APP_URL, SITE_CONFIG.url),
    digestEnabled: readBoolean(source.TASKFLOW_DIGEST_ENABLED, nodeEnv !== "test"),
  };
}

export const env: AppEnv = loadEnv();
","/**
 * Structured logger. The only place `console` is allowed.
 *
 * Every line is one JSON object so job output and request output can be
 * grepped the same way. The threshold comes from `TASKFLOW_LOG_LEVEL`, or
 * defaults to `warn` under test so a suite run stays quiet.
 */
import { env } from "@/config/env";

export type LogFields = Readonly<Record<string, string | number | boolean | null>>;

export type Logger = {
  debug: (message: string, fields?: LogFields) => void;
  info: (message: string, fields?: LogFields) => void;
  warn: (message: string, fields?: LogFields) => void;
  error: (message: string, fields?: LogFields) => void;
};

type Level = "debug" | "info" | "warn" | "error";

const LEVEL_RANK: Readonly<Record<Level, number>> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
};

function configuredLevel(): Level {
  const raw = (process.env.TASKFLOW_LOG_LEVEL ?? "").trim().toLowerCase();
  if (raw in LEVEL_RANK) return raw as Level;
  if (env.nodeEnv === "test") return "warn";
  return env.nodeEnv === "production" ? "info" : "debug";
}

const threshold = LEVEL_RANK[configuredLevel()];

function write(level: Level, scope: string, message: string, fields?: LogFields): void {
  if (LEVEL_RANK[level] < threshold) return;

  const line = JSON.stringify({
    level,
    scope,
    message,
    time: new Date().toISOString(),
    ...(fields ?? {}),
  });

  // This module is the sanctioned `console` sink; nothing else may call it.
  if (level === "error") console.error(line);
  else if (level === "warn") console.warn(line);
  else console.log(line);
}

/**
 * A logger bound to one scope, e.g. `createLogger("issue-service")`. Scopes
 * are module-shaped so a log line always names the code that emitted it.
 */
export function createLogger(scope: string): Logger {
  return {
    debug: (message, fields) => write("debug", scope, message, fields),
    info: (message, fields) => write("info", scope, message, fields),
    warn: (message, fields) => write("warn", scope, message, fields),
    error: (message, fields) => write("error", scope, message, fields),
  };
}
","/**
 * Result envelope every job returns to the scheduler.
 */
import { toIsoTimestamp } from "@/types/common";
import type { IsoTimestamp } from "@/types/common";

export type JobResult = {
  kind: string;
  processed: number;
  failed: number;
  durationMs: number;
  startedAt: IsoTimestamp;
};

/** The zero value a job starts from and mutates as it works. */
export function emptyJobResult(
  kind: string,
  startedAt: IsoTimestamp,
): JobResult {
  return { kind, processed: 0, failed: 0, durationMs: 0, startedAt };
}

/**
 * Convenience for a job body: stamps the start, runs the work and fills in
 * `durationMs`. Kept here so every job reports the same shape.
 */
export async function runJob(
  kind: string,
  work: (result: JobResult) => Promise<void>,
): Promise<JobResult> {
  const startedAt = toIsoTimestamp(new Date());
  const began = Date.now();
  const result = emptyJobResult(kind, startedAt);

  await work(result);

  return { ...result, durationMs: Date.now() - began };
}
","/**
 * Organization rows plus slug uniqueness lookups.
 *
 * Must call (do not reimplement): archivePatch, uniqueSlug
 */
import { and, eq, isNull, like } from "drizzle-orm";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  return row ? toOrganization(row) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Creates the org row. The slug is de-duplicated here rather than in the
 * service so a race on the unique index still resolves to a usable slug.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  const taken = await listTakenOrgSlugs(input.slug);
  const slug = uniqueSlug(input.slug, taken);
  const stamp = toIsoTimestamp(new Date());

  const row = getDb()
    .insert(organizations)
    .values({
      id: newId(),
      name: input.name,
      slug,
      ownerId,
      plan: input.plan,
      logoUrl: null,
      trialEndsAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toOrganization(row);
}

export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
