 * Organization overview: recent issues, project stats and usage.
 *
 * Owner D. Three panels, each behind its own permission — a viewer sees the
 * issues and the projects but not the usage meters, because usage is billing
 * information.
 *
 * Must call (do not reimplement): can
 */

import Link from "next/link";
import type { Metadata } from "next";
import { IssueCard } from "@/components/domain/issue/issue-card";
import { ProjectCard } from "@/components/domain/project/project-card";
import { UsagePanel } from "@/components/domain/billing/usage-panel";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { getBillingSummary } from "@/server/services/billing-service";
import { listIssues } from "@/server/services/issue-service";
import { listProjects } from "@/server/services/project-service";
import type { BillingSummary } from "@/types/billing";
import { loadTenantContext } from "./_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Overview",
};

const RECENT_ISSUE_LIMIT = 8;
const PROJECT_LIMIT = 6;

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const mayReadBilling = can(actor, "org:manage_billing", {
    kind: "billing",
    orgId: org.id,
  });

  const [issues, projects, billing] = await Promise.all([
    listIssues(actor, {
      orgId: org.id,
      assigneeId: actor.userId,
      status: ["todo", "in_progress", "in_review"],
      limit: RECENT_ISSUE_LIMIT,
    }),
    listProjects(actor, { orgId: org.id, limit: PROJECT_LIMIT }),
    mayReadBilling
      ? getBillingSummary(actor, org.id)
      : Promise.resolve<BillingSummary | null>(null),
  ]);

  return (
    <div className="space-y-12">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">{org.name}</h1>
        <p className="mt-1 text-sm text-slate-600">
          {projects.total} projects · {issues.total} issues assigned to you
        </p>
      </header>

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Assigned to you
          </h2>
          <Link href={`/${orgSlug}/issues`} className="text-sm text-indigo-600">
            All issues
          </Link>
        </div>

        {issues.items.length === 0 ? (
          <EmptyState
            title="Nothing on your plate"
            description="Issues assigned to you show up here as soon as somebody picks you."
          />
        ) : (
          <ul className="space-y-2">
            {issues.items.map((issue) => (
              <li key={issue.id}>
                <IssueCard
                  issue={issue}
                  href={`/${orgSlug}/issues?issue=${issue.id}`}
                  compact
                />
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <div className="mb-4 flex items-baseline justify-between">
          <h2 className="text-sm font-semibold uppercase tracking-wide text-slate-500">
            Projects
          </h2>
          <Link href={`/${orgSlug}/projects`} className="text-sm text-indigo-600">
            All projects
          </Link>
        </div>

        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {projects.items.map((row) => (
            <ProjectCard
              key={row.project.id}
              project={row.project}
              stats={row.stats}
              href={`/${orgSlug}/projects/${row.project.slug}`}
              actor={actor}
            />
          ))}
        </div>
      </section>

      {billing !== null ? (
        <section>
          <h2 className="mb-4 text-sm font-semibold uppercase tracking-wide text-slate-500">
            Usage
          </h2>
          <UsagePanel summary={billing} />
        </section>
      ) : null}
    </div>
  );
}
","/**
 * All quota meters for the organization.
 *
 * Must call (do not reimplement): getPlanLimits
 */
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { getPlanLimits } from "@/config/plan-limits";
import { formatDate } from "@/lib/date";
import type { BillingSummary, LimitedResource } from "@/types/billing";
import type { ReactElement } from "react";
import { UsageMeter } from "./usage-meter";

export type UsagePanelProps = { summary: BillingSummary };

/** Human labels for the quota dimensions, in the order the panel shows them. */
export const RESOURCE_LABELS: Readonly<Record<LimitedResource, string>> = {
  seats: "Seats",
  projects: "Projects",
  issuesPerProject: "Issues per project",
  storageMb: "Storage (MB)",
  apiRequestsPerHour: "API requests / hour",
  webhooks: "Webhooks",
};

const RESOURCE_ORDER: readonly LimitedResource[] = [
  "seats",
  "projects",
  "issuesPerProject",
  "storageMb",
  "apiRequestsPerHour",
  "webhooks",
];

export function UsagePanel(props: UsagePanelProps): ReactElement | null {
  const { summary } = props;
  // The subscription says which plan; the plan table says what it includes.
  const limits = getPlanLimits(summary.subscription.plan);

  const byResource = new Map(
    summary.checks.map((check) => [check.resource, check]),
  );

  return (
    <Card padded>
      <CardHeader>
        <CardTitle>Usage on the {limits.plan} plan</CardTitle>
      </CardHeader>

      <CardContent>
        <div className="space-y-3">
          {RESOURCE_ORDER.map((resource) => {
            const check = byResource.get(resource);
            if (check === undefined) return null;
            return (
              <UsageMeter
                key={resource}
                check={check}
                label={RESOURCE_LABELS[resource]}
              />
            );
          })}
        </div>

        <p className="mt-3 text-xs text-neutral-500">
          Data is retained for {limits.retentionDays} days. Current period ends{" "}
          {formatDate(summary.subscription.currentPeriodEnd)}.
        </p>
      </CardContent>
    </Card>
  );
}
","/**
 * Determinate progress bar; the usage meter builds on it.
 *
 * Owner A — design system. Presentational: the plan-limit maths lives in
 * `@/config/plan-limits` and reaches this component as a plain ratio, so no
 * limit number is ever hardcoded here.
 */
import type { ReactElement } from "react";
import { cn } from "@/lib/cn";
import { TONE_FILL } from "./_lib/tokens";

export type ProgressProps = { value: number; max?: number; tone?: 'brand' | 'warning' | 'danger'; label?: string };

/** Clamp to 0–100 so a stale count above the limit cannot overflow the track. */
export function progressPercent(value: number, max: number): number {
  if (!Number.isFinite(value) || !Number.isFinite(max) || max <= 0) return 0;
  return Math.min(100, Math.max(0, Math.round((value / max) * 100)));
}

export function Progress(props: ProgressProps): ReactElement | null {
  const { value, max = 100, tone = "brand", label } = props;

  const percent = progressPercent(value, max);

  return (
    <div className="flex flex-col gap-1">
      {label !== undefined ? (
        <div className="flex items-baseline justify-between text-xs text-black/60 dark:text-white/60">
          <span>{label}</span>
          <span className="tabular-nums">{percent}%</span>
        </div>
      ) : null}
      <div
        role="progressbar"
        aria-valuenow={value}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-label={label}
        className="h-2 w-full overflow-hidden rounded-full bg-black/10 dark:bg-white/15"
      >
        <div
          style={{ width: `${percent}%` }}
          className={cn("h-full rounded-full transition-all", TONE_FILL[tone])}
        />
      </div>
    </div>
  );
}
","/**
 * Progress bar for one `LimitCheck`.
 */
import { Progress, type ProgressProps } from "@/components/ui/progress";
import { UNLIMITED } from "@/config/plan-limits";
import { formatCount, formatLimit } from "@/lib/format";
import type { LimitCheck } from "@/types/billing";
import type { ReactElement } from "react";

export type UsageMeterProps = { check: LimitCheck; label?: string };

/** Warn before the wall, not at it. */
export const USAGE_WARNING_RATIO = 0.8;

export function usageRatio(check: LimitCheck): number {
  if (!Number.isFinite(check.limit) || check.limit <= 0) return 0;
  return Math.min(1, check.used / check.limit);
}

export function usageTone(check: LimitCheck): NonNullable<ProgressProps["tone"]> {
  if (check.exceeded) return "danger";
  return usageRatio(check) >= USAGE_WARNING_RATIO ? "warning" : "brand";
}

export function UsageMeter(props: UsageMeterProps): ReactElement | null {
  const { check, label } = props;
  const unlimited = check.limit === UNLIMITED || !Number.isFinite(check.limit);

  return (
    <div className="usage-meter space-y-1">
      <div className="flex items-baseline justify-between text-sm">
        <span>{label ?? check.resource}</span>
        <span className="text-neutral-500">
          {formatCount(check.used)} / {formatLimit(check.limit)}
        </span>
      </div>

      {unlimited ? null : (
        <Progress
          value={check.used}
          max={check.limit}
          tone={usageTone(check)}
          label={label ?? check.resource}
        />
      )}

      {check.exceeded ? (
        <p className="text-xs text-red-600">
