","/**
 * Compact issue summary tile used by lists and the board.
 */
import Link from "next/link";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/cn";
import { formatRelative, isOverdue } from "@/lib/date";
import { humanizePriority, humanizeStatus } from "@/lib/format";
import type { Issue, IssueLabel, IssuePriority } from "@/types/issue";
import type { User } from "@/types/member";
import type { ReactElement } from "react";
import { PRIORITY_TONE, STATUS_TONE } from "./issue-tone";

export type IssueCardProps = {
  issue: Issue;
  assignee?: User | null;
  labels?: readonly IssueLabel[];
  href: string;
  compact?: boolean;
};

/** Priorities worth shouting about; `none`/`low` stay silent on a card. */
function shouldShowPriority(priority: IssuePriority): boolean {
  return priority !== "none" && priority !== "low";
}

export function IssueCard(props: IssueCardProps): ReactElement | null {
  const { issue, assignee = null, labels = [], href, compact = false } = props;
  const overdue = isOverdue(issue.dueAt);

  return (
    <Card padded={!compact} className="issue-card">
      <div className={cn("flex items-start gap-3", compact && "text-sm")}>
        <div className="min-w-0 flex-1">
          <Link href={href} className="block font-medium hover:underline">
            <span className="mr-2 text-neutral-500">#{issue.number}</span>
            {issue.title}
          </Link>

          <div className="mt-1 flex flex-wrap items-center gap-2">
            <Badge tone={STATUS_TONE[issue.status]} size="sm">
              {humanizeStatus(issue.status)}
            </Badge>

            {shouldShowPriority(issue.priority) ? (
              <Badge tone={PRIORITY_TONE[issue.priority]} size="sm">
                {humanizePriority(issue.priority)}
              </Badge>
            ) : null}

            {labels.map((label) => (
              <Badge key={label.id} tone="neutral" size="sm">
                {label.name}
              </Badge>
            ))}

            {issue.dueAt !== null ? (
              <span className={cn("text-xs", overdue && "text-red-600")}>
                {overdue ? "overdue " : "due "}
                {formatRelative(issue.dueAt)}
              </span>
            ) : null}

            {issue.archivedAt !== null ? (
              <Badge tone="warning" size="sm">
                Archived
              </Badge>
            ) : null}
          </div>
        </div>

        {assignee !== null ? (
          <Avatar name={assignee.name} src={assignee.avatarUrl} size="sm" />
        ) : (
          <Badge tone="neutral" size="sm">
            Unassigned
          </Badge>
        )}
      </div>
    </Card>
  );
}
","/**
 * Project tile with open/closed counts.
 *
 * Must call (do not reimplement): can
 */
import Link from "next/link";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { formatCount } from "@/lib/format";
import { formatRelative } from "@/lib/date";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import type { Actor } from "@/types/member";
import type { Project, ProjectStats } from "@/types/project";
import type { ReactElement } from "react";
import { projectResource } from "../permission/resources";

export type ProjectCardProps = {
  project: Project;
  stats: ProjectStats;
  href: string;
  actor: Actor;
};

export function ProjectCard(props: ProjectCardProps): ReactElement | null {
  const { project, stats, href, actor } = props;
  const resource = projectResource(project);

  // A project the actor cannot read must not even leak its name.
  if (!can(actor, "project:read", resource)) return null;

  const mayUpdate = can(actor, "project:update", resource);

  return (
    <Card padded>
      <CardHeader>
        <CardTitle>
          <Link href={href} className="hover:underline">
            {project.name}
          </Link>
        </CardTitle>
        <span className="ml-2 text-xs text-neutral-500">{project.key}</span>
        {isArchived(project) ? (
          <Badge tone="warning" size="sm">
            Archived
          </Badge>
        ) : null}
        {project.visibility === "public" ? (
          <Badge tone="brand" size="sm">
            Public
          </Badge>
        ) : null}
      </CardHeader>

      <CardContent>
        <p className="text-sm text-neutral-600">
          {project.description ?? "No description."}
        </p>

        <dl className="mt-2 flex gap-4 text-sm">
          <span>
            <dt className="inline text-neutral-500">Open </dt>
            <dd className="inline font-medium">
              {formatCount(stats.openIssues)}
            </dd>
          </span>
          <span>
            <dt className="inline text-neutral-500">Closed </dt>
            <dd className="inline font-medium">
              {formatCount(stats.closedIssues)}
            </dd>
          </span>
          {stats.overdueIssues > 0 ? (
            <span className="text-red-600">
              <dt className="inline">Overdue </dt>
              <dd className="inline font-medium">
                {formatCount(stats.overdueIssues)}
              </dd>
            </span>
          ) : null}
        </dl>

        {stats.lastActivityAt !== null ? (
          <p className="mt-1 text-xs text-neutral-500">
            Last activity {formatRelative(stats.lastActivityAt)}
          </p>
        ) : null}

        {mayUpdate ? (
          <Link
            href={`${href}/settings`}
            className="mt-2 inline-block text-xs text-indigo-600 hover:underline"
          >
            Project settings
          </Link>
        ) : null}
      </CardContent>
    </Card>
  );
}
